    /**
     * assign Bank on ThirdPartyProvider
     * @param		command AssignBankToThirdPartyProviderCommand	
     * @exception	ProcessingException
     */     
	public void assignBank( AssignBankToThirdPartyProviderCommand command ) throws ProcessingException {

		// --------------------------------------------
		// load the parent
		// --------------------------------------------
		load( command.getThirdPartyProviderId() );
		
		BankService childDelegate 	= BankService.getBankInstance();
		ThirdPartyProviderService parentDelegate = ThirdPartyProviderService.getThirdPartyProviderInstance();			
		UUID childId = command.getAssignment().getBankId();
		Bank child = null;
		
		try {
			// --------------------------------------
	    	// best to validate the command now
	    	// --------------------------------------    
	    	ThirdPartyProviderValidator.getInstance().validate( command );    

	    	// --------------------------------------
        	// issue the command
        	// --------------------------------------    	
    		commandGateway.sendAndWait( command );

		}
        catch( Throwable exc ) {
			final String msg = "Failed to get Bank using id " + childId;
			LOGGER.log( Level.WARNING,  msg );
			throw new ProcessingException( msg, exc );
        }
	}

